type ReadMode = ReviewerReadLogEvent['mode'];

const DEFAULT_REQUIREMENTS_DIR = 'docs/requirements';
const CONTROL_CHARS = /[\u0000-\u001f\u007f]/;
const SHA256_HEX = /^[a-f0-9]{64}$/;
